{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Grounded Aromatic Support</title>
  <meta name='description' content='A boutique aromatherapy practice offering focused, safety-forward scent sessions and custom blends that may support calm, focus, and restful moments.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
</head>
<body class='layout-earthy'>
  <svg class='site-pattern' aria-hidden='true'>
    <defs>
      <pattern id='p' patternUnits='userSpaceOnUse' width='120' height='120'>
        <image href='assets/img/pattern.svg' x='0' y='0' width='120' height='120'/>
      </pattern>
    </defs>
    <rect width='100%' height='100%' fill='url(#p)'></rect>
  </svg>

  <header class='site-header'>
    <div class='wrap'>
      <a class='brand' href='index.html' aria-label='Home'>
        <strong>{{BUSINESS_NAME}}</strong>
        <small>Practitioner of considered scent</small>
      </a>
      <nav class='main-nav' aria-label='Primary'>
        <ul>
          <li><a href='index.html'>Home</a></li>
          <li><a href='services.html'>Offerings</a></li>
          <li><a href='blends.html'>Custom Blends</a></li>
          <li><a href='shop.html'>Shop</a></li>
          <li><a href='pricing.html'>Rates</a></li>
          <li><a href='about.html'>About</a></li>
          <li><a href='book.html' class='cta'>Book a Session</a></li>
          <li><a href='contact.html'>Connect</a></li>
        </ul>
      </nav>
      <button class='mobile-toggle' aria-expanded='false' aria-controls='mobile-menu'>Menu</button>
    </div>
  </header>

  <main>
    <section class='hero reveal' data-reveal>
      <div class='wrap'>
        <div class='hero-text'>
          <h1>Small scent practices that may support clearer moments</h1>
          <p class='lead'>A safety-first aromatherapy practice offering focused sessions and personalized blends to help you create gentle daily rituals.</p>
          <div class='hero-ctas'>
            <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
            <button class='btn ghost' id='try-now'>Try a Moment</button>
          </div>
        </div>
        <aside class='hero-info'>
          <p><strong>Phone:</strong> <a href='tel:{{PHONE}}'>{{PHONE}}</a></p>
          <p><strong>Email:</strong> <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></p>
          <p class='location'>Serving {{CITY}}, {{STATE}}</p>
        </aside>
      </div>
    </section>

    <section class='social-proof reveal' data-reveal>
      <div class='wrap'>
        <h2>Client Notes</h2>
        <div class='testimonials'>
          <blockquote>"A gentle, practical approach to scent—I've adopted a nightly blend that helps me shift out of work mode." — J.R.</blockquote>
          <blockquote>"Practical guidance and clear safety advice. My dog tolerated recommended blends with no issues." — M.S.</blockquote>
        </div>
      </div>
    </section>

    <section class='benefits reveal' data-reveal>
      <div class='wrap'>
        <h2>What you might experience</h2>
        <ul>
          <li><strong>Focused Rituals</strong> — short, repeatable scent practices for morning or evening.
          </li>
          <li><strong>Custom Support</strong> — blends tailored for personal routines that may support mood and calm.
          </li>
          <li><strong>Safety-first Guidance</strong> — dilution, patch-test, and pet considerations discussed in every session.
          </li>
        </ul>
      </div>
    </section>

    <section class='process reveal' data-reveal>
      <div class='wrap'>
        <h2>How a VIP Day works</h2>
        <ol>
          <li><strong>Intake & goals</strong> — we map your rhythms and sensitivities.</li>
          <li><strong>Blend crafting</strong> — a focused selection of safe dilutions and application notes.</li>
          <li><strong>Implementation plan</strong> — a single-day deep session to produce blends, usage guides, and follow-up notes.</li>
        </ol>
        <p class='note'>This is our VIP Day offer: an intensive, collaborative day to set a scent plan you can use right away.</p>
      </div>
    </section>

    <section class='faq reveal' data-reveal>
      <div class='wrap'>
        <h2>Common Questions</h2>
        <details>
          <summary>Are these approaches medical treatments?</summary>
          <div>
            <p>No. Aromatherapy approaches described here may support wellbeing but are not medical care. Always consult a healthcare professional for medical concerns.</p>
          </div>
        </details>
        <details>
          <summary>How do you handle dilution and patch testing?</summary>
          <div>
            <p>We recommend safe dilutions for topical use and demonstrate patch testing before regular application. Typical carrier ratios and stepwise testing are provided for home use.</p>
          </div>
        </details>
        <details>
          <summary>What about pets and pregnancy?</summary>
          <div>
            <p>Some essential oils are not appropriate for pets or pregnancy. We review alternatives and avoidance strategies as part of every session.</p>
          </div>
        </details>
      </div>
    </section>

    <section class='callout reveal' data-reveal>
      <div class='wrap'>
        <h2>Ready to create a simple scent routine?</h2>
        <p>Book a focused VIP Day or pick a guided session that fits your schedule.</p>
        <a class='btn primary' href='book.html'>Reserve a VIP Day</a>
      </div>
    </section>
  </main>

  <footer class='site-footer'>
    <div class='wrap'>
      <nav>
        <ul>
          <li><a href='about.html'>About</a></li>
          <li><a href='contact.html'>Contact</a></li>
          <li><a href='privacy.html'>Privacy</a></li>
        </ul>
      </nav>
      <p>Contact: <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a> • <a href='tel:{{PHONE}}'>{{PHONE}}</a></p>
      <p class='copyright'>© <span class='year'>2026</span> {{BUSINESS_NAME}}</p>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id='guide-modal' class='modal' aria-hidden='true' role='dialog' aria-modal='true'>
    <div class='modal-panel'>
      <button class='modal-close' aria-label='Close'>Close</button>
      <h3>Try a Moment</h3>
      <p class='modal-desc'>Choose a short guided practice: breathing, journaling, or intention-setting.</p>
      <div class='guide-controls'>
        <button class='guide-btn' data-mode='breath'>Breathing (2 min)</button>
        <button class='guide-btn' data-mode='journal'>Journaling (5 min)</button>
        <button class='guide-btn' data-mode='intention'>Set an Intention</button>
      </div>

      <div class='guide-stage' aria-live='polite'>
        <div class='breath-visual' aria-hidden='true'>
          <svg viewBox='0 0 200 200' class='breath-svg'>
            <circle cx='100' cy='100' r='50' class='breath-circle'></circle>
          </svg>
        </div>
        <div class='guide-text'></div>
        <div class='guide-actions'>
          <button class='btn primary' id='start-guide'>Start</button>
          <button class='btn ghost' id='reset-guide'>Reset</button>
        </div>
      </div>
    </div>
  </div>

  <div id='overlay' class='overlay' hidden></div>

  <script src='assets/js/main.js' defer></script>
</body>
</html>"} 
