{"path":"assets/css/styles.css","content":"/* Earthy warm theme */
:root{
  --bg:#fbf7f2;
  --card:#fff7f2;
  --accent:#7b5e3c;
  --muted:#8b7760;
  --accent-2:#c19a6b;
  --glass:rgba(255,255,255,0.6);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:#2d2d2d;background:var(--bg);}
.wrap{max-width:1100px;margin:0 auto;padding:2rem}
.site-pattern{position:fixed;inset:0;opacity:0.08;pointer-events:none}
.site-header{background:linear-gradient(180deg,var(--card),transparent);backdrop-filter:blur(4px);position:sticky;top:0;z-index:40;border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;padding:1rem}
.brand{display:flex;flex-direction:column;text-decoration:none;color:var(--accent)}
.brand strong{font-size:1.1rem}
.main-nav ul{display:flex;gap:1rem;list-style:none;margin:0;padding:0}
.main-nav a{color:var(--muted);text-decoration:none;padding:.4rem .6rem;border-radius:6px}
.main-nav a.cta{background:var(--accent);color:#fff}
.mobile-toggle{display:none}
.hero{display:grid;grid-template-columns:1fr 320px;gap:2rem;align-items:center;padding:4rem 0}
.hero .lead{color:var(--muted);margin-top:.5rem}
.btn{display:inline-block;padding:.6rem 1rem;border-radius:8px;border:1px solid transparent;text-decoration:none;cursor:pointer}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid var(--accent-2);color:var(--accent)}
.hero-info p{margin:.4rem 0;color:var(--muted)}
.testimonials{display:flex;gap:1rem;flex-wrap:wrap}
.testimonials blockquote{background:var(--card);padding:1rem;border-radius:8px;flex:1 1 300px;border-left:4px solid var(--accent-2);margin:0}
.benefits ul{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;list-style:none;padding:0}
.benefits li{background:var(--card);padding:1rem;border-radius:8px}
.process ol{margin-left:1rem}
.faq details{background:var(--card);padding:1rem;border-radius:8px;margin-bottom:.5rem}
.callout{background:linear-gradient(90deg,rgba(193,154,107,0.06),transparent);padding:2rem;border-radius:12px;text-align:center}
.site-footer{padding:2rem 0;color:var(--muted)}
.site-footer nav ul{display:flex;gap:1rem;list-style:none;padding:0}
.modal{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:1rem;z-index:60;visibility:hidden;opacity:0;transition:opacity .2s ease,visibility .2s}
.modal[aria-hidden='false']{visibility:visible;opacity:1}
.modal-panel{background:var(--card);padding:1.5rem;border-radius:12px;max-width:640px;width:100%;box-shadow:0 6px 30px rgba(40,30,20,0.12)}
.modal-close{float:right;background:none;border:0;color:var(--muted);cursor:pointer}
.guide-controls{display:flex;gap:.5rem;flex-wrap:wrap;margin:.5rem 0}
.breath-svg{width:160px;height:160px;display:block;margin:1rem auto}
.breath-circle{fill:var(--accent);opacity:.12;transition:transform 2s ease}
.guide-text{min-height:3rem;text-align:center}
.guide-actions{display:flex;gap:.5rem;justify-content:center;margin-top:.5rem}
.overlay{position:fixed;inset:0;background:rgba(20,10,5,0.3);z-index:50}

/* Reveal animation */
.reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
.reveal.show{opacity:1;transform:none}

/* Reduced motion */
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none;opacity:1;transform:none}
  .breath-circle{transition:none}
}

/* Responsive */
@media(max-width:860px){
  .hero{grid-template-columns:1fr;}
  .main-nav ul{display:none}
  .mobile-toggle{display:inline-block}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  'use strict'

  // Simple mobile toggle
  var mobileToggle=document.querySelector('.mobile-toggle')
  var nav=document.querySelector('.main-nav')
  mobileToggle&&mobileToggle.addEventListener('click',function(){
    var expanded=this.getAttribute('aria-expanded')==='true'
    this.setAttribute('aria-expanded', String(!expanded))
    if(!expanded){ nav.style.display='block' } else { nav.style.display='none' }
  })

  // Scroll reveal with prefers-reduced-motion support
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
  if(prefersReduced){
    document.querySelectorAll('[data-reveal]').forEach(function(el){ el.classList.add('show') })
  } else if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){ e.target.classList.add('show'); io.unobserve(e.target) }
      })
    },{threshold:0.12})
    document.querySelectorAll('[data-reveal]').forEach(function(el){ io.observe(el) })
  } else {
    // fallback: show all
    document.querySelectorAll('[data-reveal]').forEach(function(el){ el.classList.add('show') })
  }

  // Guided exercise modal logic
  var tryBtn=document.getElementById('try-now')
  var modal=document.getElementById('guide-modal')
  var overlay=document.getElementById('overlay')
  var closeBtn=document.querySelector('.modal-close')
  var guideBtns=document.querySelectorAll('.guide-btn')
  var startBtn=document.getElementById('start-guide')
  var resetBtn=document.getElementById('reset-guide')
  var guideText=document.querySelector('.guide-text')
  var breathCircle=document.querySelector('.breath-circle')
  var currentMode=null
  var breathTimer=null
  var breathPhase=0

  function openModal(){ modal.setAttribute('aria-hidden','false'); overlay.hidden=false }
  function closeModal(){ modal.setAttribute('aria-hidden','true'); overlay.hidden=true; stopBreathing() }

  tryBtn&&tryBtn.addEventListener('click',openModal)
  closeBtn&&closeBtn.addEventListener('click',closeModal)
  overlay&&overlay.addEventListener('click',closeModal)

  guideBtns.forEach(function(b){ b.addEventListener('click',function(){
    guideBtns.forEach(function(x){ x.classList.remove('active') })
    b.classList.add('active')
    currentMode=b.getAttribute('data-mode')
    updateGuideText('selected')
  })})

  startBtn&&startBtn.addEventListener('click',function(){
    if(!currentMode){ updateGuideText('pick') ; return }
    if(currentMode==='breath') startBreathing()
    else if(currentMode==='journal') startJournaling()
    else if(currentMode==='intention') startIntention()
  })

  resetBtn&&resetBtn.addEventListener('click',function(){ stopBreathing(); updateGuideText('reset') })

  function updateGuideText(state){
    if(state==='pick'){
      guideText.textContent='Please pick a practice to begin.'
    } else if(state==='selected'){
      if(currentMode==='breath') guideText.textContent='A two-minute breathing practice: follow the expansion of the circle.'
      if(currentMode==='journal') guideText.textContent='A short journaling prompt will be shown; write freely for five minutes.'
      if(currentMode==='intention') guideText.textContent='Set a single short intention you can remember through the day.'
    } else if(state==='reset'){
      guideText.textContent='The practice has been reset. Choose another or close the window.'
    }
  }

  function startBreathing(){
    var totalCycles=6 // approx 2 minutes (inhale 4s, hold 2s, exhale 4s)
    var count=0
    breathPhase=0
    updateGuideText('selected')
    // accessibility: announce
    guideText.textContent='Begin: inhale as the circle expands. Exhale as it contracts.'
    // animate circle via transform
    function cycle(){
      if(count>=totalCycles){ stopBreathing(); guideText.textContent='Practice complete. Take a moment and return when ready.'; return }
      // inhale expand
      breathCircle.style.transform='scale(1.6)'
      setTimeout(function(){
        // hold - small pause
        setTimeout(function(){
          // exhale contract
          breathCircle.style.transform='scale(1)'
          setTimeout(function(){
            count++
            cycle()
          },4000) // exhale duration
        },2000) // hold
      },4000) // inhale
    }
    cycle()
  }

  function stopBreathing(){
    if(breathTimer){ clearTimeout(breathTimer); breathTimer=null }
    if(breathCircle) breathCircle.style.transform='scale(1)'
  }

  function startJournaling(){
    // Provide a prompt and a simple auto-timer
    guideText.innerHTML='Prompt: What small change would make your day easier?\nWrite for five minutes.'
    // Create a simple inline textarea if not present
    var stage=document.querySelector('.guide-stage')
    var ta=stage.querySelector('textarea')
    if(!ta){ ta=document.createElement('textarea'); ta.rows=8; ta.placeholder='Write freely...'; ta.style.width='100%'; ta.style.marginTop='1rem'; stage.appendChild(ta) }
    ta.focus()
  }

  function startIntention(){
    guideText.textContent='Choose one short intention (a sentence or a few words) and say it aloud or write it down.'
    var stage=document.querySelector('.guide-stage')
    var input=stage.querySelector('input')
    if(!input){ input=document.createElement('input'); input.type='text'; input.placeholder='My intention is...'; input.style.width='100%'; input.style.marginTop='1rem'; stage.appendChild(input) }
    var inputEl=stage.querySelector('input')
    inputEl.focus()
  }

  // accessible year update
  document.querySelectorAll('.year').forEach(function(el){ el.textContent=new Date().getFullYear() })

})();
"} 
